import {emptyScientificPack,parseScientificPack,scientificInstrumentChannels,type ScientificInstrumentKind} from '../../src/lib/scientificWorkspace';
/** Synthetic regression-only investigation; never shipped as a course. */
export const syntheticScientificPack=(kind:ScientificInstrumentKind='manual')=>{const base=emptyScientificPack('synthetic-'+kind),channels=scientificInstrumentChannels(kind);return parseScientificPack({...base,title:'Synthetic '+kind+' investigation',description:'Compare bounded educational observations and design alternatives.',sourceNote:'Original synthetic regression fixture only; not empirical research or safety guidance.',safety:'Use fictional observations or idealized models only. No real equipment or substances.',assumptions:'Values are illustrative; model or declared bounds do not establish physical validity.',steps:[{id:'observe',title:'Record a controlled comparison',instructions:'Hold other settings fixed and explain the observation.',adult:false}],instrument:{kind},channels,graph:{xChannelId:channels[0].id,yChannelId:channels[1].id},design:{brief:'Compare an initial design with an alternative and discuss limitations.',criteria:[{id:'target',title:'Illustrative target',channelId:channels[1].id,min:kind==='manual'?4:0,max:kind==='manual'?6:Math.min(1000,channels[1].max)}]}});};
